window.futvizVista("xa-vs-asistencias-90","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"xa-vs-asistencias-90\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"xa-vs-asistencias-90\"]={\"id\":\"xa-vs-asistencias-90\",\"titulo\":\"xA vs. asistencias por 90'\",\"bajada\":\"Sobre la diagonal dio m\u00e1s asistencias que su xA; a la derecha de la l\u00ednea, el 20% con m\u00e1s xA.\",\"pregunta\":\"\u00bfQui\u00e9n da m\u00e1s asistencias de las que deber\u00eda?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xA90\",\"label\":\"xA por 90'\",\"corto\":\"xA por 90'\",\"dec\":2},\"y\":{\"col\":\"a90\",\"label\":\"Asistencias por 90'\",\"corto\":\"Asistencias por 90'\",\"dec\":2},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"asistencias \u2212 xA por 90'\",\"sobre\":\"Asisten m\u00e1s de lo esperado\",\"bajo\":\"Asisten menos de lo esperado\",\"decDif\":2,\"zonas\":{\"pct\":0.8,\"variable\":\"xA por 90'\",\"tl\":\"Crean poco pero les anotan\",\"tr\":\"Crean mucho y les anotan\",\"bl\":\"Crean poco y les fallan\",\"br\":\"Crean mucho pero les fallan\"}},\"requiere\":[\"xA90\",\"a90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xA por 90'\",\"ayuda\":\"Ordenados por xA por 90'\"},{\"id\":\"y\",\"etiqueta\":\"Asistencias por 90'\",\"ayuda\":\"Ordenados por Asistencias por 90'\"}],\"queMirar\":\"A la derecha, los que dan pases de m\u00e1s peligro por 90' (xA); arriba, los que m\u00e1s asistencias dan. Por encima de la diagonal, jugadores cuyos compa\u00f1eros definieron mejor de lo esperado lo que les pusieron; debajo, los que los convirtieron menos. Ojo: casi todos est\u00e1n debajo, porque las asistencias suman cerca del 90% del xA.\\n\\nLa l\u00ednea vertical deja a su derecha al 20% con m\u00e1s xA. **Arriba a la derecha**: crean mucho y les anotan. **Abajo a la derecha**: crean mucho y les fallan. **Arriba a la izquierda**: crean poco pero les anotan. **Abajo a la izquierda**: crean poco y les fallan. Haz clic en un cuadrante para acercarte.\",\"insight\":\"xa_asist_90\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\",\"rendimiento\"],\"minimoPor90\":true,\"posicionesIni\":[\"Defensa\",\"Medio\",\"Delantero\"]};</script>");